#### Example 1: Component Structure

```typescript
// src/components/Button/Button.tsx
import React from 'react';
import { cn } from '../../utils/classnames';
import './Button.css';

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'tertiary' | 'danger';
  size?: 'sm' | 'md' | 'lg';
  fullWidth?: boolean;
  loading?: boolean;
}

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({
    children,
    variant = 'primary',
    size = 'md',
    fullWidth = false,
    loading = false,
    disabled,
    className,
    ...props
  }, ref) => {
    return (
      <button
        ref={ref}
        className={cn(
          'gw-button',
          `gw-button--${variant}`,
          `gw-button--${size}`,
          fullWidth && 'gw-button--full-width',
          loading && 'gw-button--loading',
          className
        )}
        disabled={disabled || loading}
        aria-disabled={disabled || loading}
        {...props}
      >
        {loading && <span className="gw-button__spinner" aria-hidden="true" />}
        <span className="gw-button__content">{children}</span>
      </button>
    );
  }
);

Button.displayName = 'Button';
```

